+const { useState } = React;
+
+const NotificationForm = () => {
+  const [preference, setPreference] = useState('');
+
+  const handleSubmit = (e) => {
+    e.preventDefault();
+    if (!preference) {
+      alert('Please select a preference');
+      return;
+    }
+    console.log('Submitted preference:', preference);
+    alert(`Selection saved: ${preference}`);
+  };
+
+  const options = [
+    { id: 'email', label: 'Email' },
+    { id: 'sms', label: 'SMS' },
+    { id: 'push', label: 'Push Notifications' }
+  ];
+
+  return (
+    <div className="container">
+      <h1>Notification Settings</h1>
+      <form onSubmit={handleSubmit} noValidate>
+        <div className="form-field">
+          <fieldset>
+            <legend>How do you prefer to receive notifications? <span aria-hidden="true">*</span></legend>
+            <div className="radio-group">
+              {options.map((option) => (
+                <div key={option.id} className="radio-option">
+                  <input
+                    type="radio"
+                    id={option.id}
+                    name="notification-preference"
+                    value={option.id}
+                    checked={preference === option.id}
+                    onChange={(e) => setPreference(e.target.value)}
+                    required
+                  />
+                  <label htmlFor={option.id}>{option.label}</label>
+                </div>
+              ))}
+            </div>
+          </fieldset>
+        </div>
+        <button type="submit">Save preference</button>
+      </form>
+    </div>
+  );
+};
+
+const domContainer = document.querySelector('#root');
+const root = ReactDOM.createRoot(domContainer);
+root.render(<NotificationForm />);
+
')

