+const { chromium } = require('playwright');
+const fs = require('fs');
+const path = require('path');
+
+async function runTest() {
+  const browser = await chromium.launch();
+  const page = await browser.newPage();
+  
+  // Need to serve the file or use setContent. 
+  // Since it uses external CSS/JS, we should load it as a file if possible, 
+  // but for simplicity and since we want a standalone HTML later, 
+  // let's try to load the current index.html which references files.
+  
+  const filePath = 'file://' + path.resolve('index.html');
+  await page.goto(filePath, { waitUntil: 'networkidle' });
+  
+  await page.addScriptTag({ path: '/tmp/axe.min.js' });
+  
+  const results = await page.evaluate(async () => {
+    return await window.axe.run();
+  });
+  
+  await browser.close();
+  
+  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
+  const bp = results.violations.filter(v => v.tags.includes('best-practice'));
+  
+  console.log(JSON.stringify({
+    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
+    bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
+  }, null, 2));
+  
+  process.exit(wcag.length > 0 ? 1 : 0);
+}
+
+runTest().catch(err => {
+  console.error(err);
+  process.exit(1);
+});
+
")

